function award(id){ if(STATS.ach[id]) return; STATS.ach[id]=1; save('d3d_stats',STATS); toast('🏆 Achievement: '+ACHS[id].split('|')[0],2800); }
const VW=800, VH=500, CELL=4, WALLH=6.8;

// ---------- renderer / scene ----------
