function vol3(x,z,max){ return Math.max(0,1-Math.hypot(x-P.x,z-P.z)/max); }
function pan3(x,z){ const d=Math.hypot(x-P.x,z-P.z)||1; return ((x-P.x)*Math.cos(P.yaw)-(z-P.z)*Math.sin(P.yaw))/d; }
