const ANCIENT_GEO={skull:new THREE.SphereGeometry(1,18,14),jaw:new THREE.SphereGeometry(1,12,9),pillar:new THREE.CylinderGeometry(.27,.31,3.35,10),bone:new THREE.CylinderGeometry(.054,.075,.9,9)};
