  const worldFoot=(leg,lead=0)=>({
    x:e.x+(leg.restX*cy+leg.restZ*sy)*scale+(e.actualVX||0)*lead,
    z:e.z+(-leg.restX*sy+leg.restZ*cy)*scale+(e.actualVZ||0)*lead
  });
