  const mat=new THREE.MeshStandardMaterial({color:col,emissive:col,emissiveIntensity:.08,roughness:.88,metalness:.015,bumpMap:skinTex,bumpScale:.055});
  const visual={stalker:'chaser',armored:'brute',crawler:'splitter',necromancer:'shooter'}[type]||type;
